    dtype = tf.float32
    dtype_hint = tf.int32
    name = "mixed_list"
    input_dict = {"value": value, "dtype": dtype, "dtype_hint": dtype_hint, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5: List of lists (2D array)
