    x2 = tf.constant(np.array([[[4.0, 12.0], [24.0, 40.0]],[[2.0, 3.0],[6.0, 7.0]]]), dtype=tf.float32)
    input_dict = {"x1": x1, "x2": x2}
    list_of_inputs.append(copy.deepcopy(input_dict))

