    shape = [2, 2]
    verify_shape = True
    allow_broadcast = False
    input_dict = {"values": values, "dtype": dtype, "shape": shape, "verify_shape": verify_shape, "allow_broadcast": allow_broadcast}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9: int16, 3D
