    input_dict = {"x": x, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 5: complex128 tensor
    x = tf.constant(np.array([1.0+1.0j, 2.0-2.0j, -1.0+0.0j, 0.0-1.0j], dtype=np.complex128))
