    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 6: Multi-dimensional float32 tensor
    x = tf.constant(np.array([[0.0, 1.0], [-1.0, 2.0]], dtype=np.float32))
    name = "sigmoid_example_6"
    input_dict = {"x": x, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

