    features = tf.constant(np.array([-1.0, -0.5, 0.0, 0.5, 1.0], dtype=np.float64)).numpy()
    name = "selu_8"
    input_dict = {"features": features, "name": name}
    list_of_inputs.append(copy.deepcopy(input_dict))

    # Input 9: Empty tensor
